import numpy as np
import collections
import craft

# Step 0: Set up references to the environment state and constants
world = env.world
state = env._current_state
grid = state.grid
start_pos = state.pos

try:
    primitive_index = world.cookbook.index[primitive]
except KeyError:
    # The requested primitive does not exist in the game's recipes
    return []

grid_width, grid_height = grid.shape[0], grid.shape[1]

# Map movement vectors (dx, dy) to their corresponding action constants
moves = {
    (-1, 0): craft.LEFT,
    (1, 0): craft.RIGHT,
    (0, -1): craft.DOWN,
    (0, 1): craft.UP,
}

# Helper function to determine if a grid cell is impassable
def is_blocked(x, y):
    return np.any(grid[x, y] > 0)

# Step 1: Find all locations of the primitive to identify target collection spots
primitive_locations = list(zip(*np.where(grid[:, :, primitive_index] > 0)))

if not primitive_locations:
    return []  # Primitive does not exist on the map, task is impossible.

# A "target spot" is an empty cell adjacent to a primitive.
# We map the spot's coordinates to its adjacent primitive's coordinates.
target_spots = {}
for px, py in primitive_locations:
    for (dx, dy), _ in moves.items():
        # Calculate the coordinates of the adjacent cell
        nx, ny = px - dx, py - dy
        if 0 <= nx < grid_width and 0 <= ny < grid_height:
            # A valid spot must be empty and not already logged
            if not is_blocked(nx, ny) and (nx, ny) not in target_spots:
                target_spots[(nx, ny)] = (px, py)

if not target_spots:
    return []  # No accessible spots to collect the primitive from.

# Step 2: Handle the edge case where the agent starts at a collection spot
if start_pos in target_spots:
    px, py = target_spots[start_pos]
    dx, dy = px - start_pos[0], py - start_pos[1]
    orient_action = moves[(dx, dy)]

    # If already facing the primitive, just USE it. Otherwise, turn first.
    if state.dir == orient_action:
        return [craft.USE]
    else:
        return [orient_action, craft.USE]

# Step 3: Use BFS to find the shortest path to the nearest collection spot
queue = collections.deque([(start_pos, [])]) # Stores ((x, y), path_list)
visited = {start_pos}

while queue:
    (curr_x, curr_y), path = queue.popleft()

    for (dx, dy), action in moves.items():
        next_pos = (curr_x + dx, curr_y + dy)
        next_x, next_y = next_pos

        # Prune search if out of bounds or already visited
        if not (0 <= next_x < grid_width and 0 <= next_y < grid_height) or next_pos in visited:
            continue

        visited.add(next_pos)
        new_path = path + [action]

        # Check if this neighbor is a target collection spot
        if next_pos in target_spots:
            primitive_pos = target_spots[next_pos]
            final_dx = primitive_pos[0] - next_x
            final_dy = primitive_pos[1] - next_y
            orient_action = moves[(final_dx, final_dy)]

            # The last move in the path sets our direction. If it's already the
            # correct orientation, we don't need another turn action.
            if action == orient_action:
                return new_path + [craft.USE]
            else:
                return new_path + [orient_action, craft.USE]

        # If it's a navigable empty cell, add it to the queue for further exploration
        if not is_blocked(next_x, next_y):
            queue.append((next_pos, new_path))

return [] # Return empty list if no path is found
